from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass(frozen=True)
class RouteKey:
    method: str
    path: str


@dataclass
class Route:
    key: RouteKey
    handler: Callable
    pass_body: bool = False


@dataclass
class Router:
    routes: dict[RouteKey, Route] = field(default_factory=dict)

    def register(self, method: str, path: str, handler: Callable, pass_body: bool = False):
        key = RouteKey(method, path)
        self.routes[key] = Route(key=key, handler=handler, pass_body=pass_body)

    def handle(self, req):
        key = RouteKey(req.method, req.path)
        route = self.routes.get(key)
        if route is None:
            return 404
        if route.pass_body:
            return route.handler(req.body)
        return route.handler()


